// Code generated by an offline NEON encoder; do not edit by hand.
// Every WORD below is the little-endian encoding of the mnemonic in its
// trailing comment, assembled and verified with the system assembler. The
// kernels are bit-exact with minMaxAbsDiff8x8PureGo (see minmax_pure_go.go).
//
// Both kernels walk the 8 rows of an 8x8 block with byte strides, compute the
// per-lane absolute difference (uabd) and fold a running per-lane min/max.
// After the row loop a horizontal uminv/umaxv reduces to scalars that match
// the reference, which scans every sample with absDiff8/absDiff16.
//
// Registers v0..v6 only are used (no v8..v15 callee-saved clobber).

//go:build arm64 && !purego

#include "textflag.h"

// func minMaxAbsDiff8x8NEON8Asm(a *byte, aStride uintptr, b *byte, bStride uintptr, out *uint32)
//
// out[0] = min absolute byte difference, out[1] = max absolute byte difference.
TEXT ·minMaxAbsDiff8x8NEON8Asm(SB), NOSPLIT, $0-40
	MOVD a+0(FP), R1
	MOVD aStride+8(FP), R3
	MOVD b+16(FP), R2
	MOVD bStride+24(FP), R4
	MOVD out+32(FP), R5
	MOVD $8, R6

	WORD $0x0f07e7e3 // movi v3.8b, #255  (running min)
	WORD $0x0f00e404 // movi v4.8b, #0    (running max)

rowLoop8:
	WORD $0x0c407020 // ld1 {v0.8b}, [x1]
	WORD $0x0c407041 // ld1 {v1.8b}, [x2]
	WORD $0x2e217402 // uabd v2.8b, v0.8b, v1.8b
	WORD $0x2e226c63 // umin v3.8b, v3.8b, v2.8b
	WORD $0x2e226484 // umax v4.8b, v4.8b, v2.8b
	ADD  R3, R1, R1
	ADD  R4, R2, R2
	SUB  $1, R6, R6
	CBNZ R6, rowLoop8

	WORD $0x2e31a865 // uminv b5, v3.8b
	WORD $0x2e30a886 // umaxv b6, v4.8b
	WORD $0x0e013cac // umov w12, v5.b[0]
	WORD $0x0e013ccd // umov w13, v6.b[0]
	MOVW R12, 0(R5)
	MOVW R13, 4(R5)
	RET

// func minMaxAbsDiff8x8NEON16Asm(a *byte, aStride uintptr, b *byte, bStride uintptr, out *uint32)
//
// Samples are little-endian unsigned 16-bit. out[0] = min, out[1] = max.
TEXT ·minMaxAbsDiff8x8NEON16Asm(SB), NOSPLIT, $0-40
	MOVD a+0(FP), R1
	MOVD aStride+8(FP), R3
	MOVD b+16(FP), R2
	MOVD bStride+24(FP), R4
	MOVD out+32(FP), R5
	MOVD $8, R6

	WORD $0x4f07a7e3 // movi v3.8h, #0xff, lsl #8  (running min hi byte)
	WORD $0x4f0797e3 // orr  v3.8h, #0xff          (running min = 0xffff)
	WORD $0x4f00e404 // movi v4.16b, #0            (running max = 0)

rowLoop16:
	WORD $0x4c407420 // ld1 {v0.8h}, [x1]
	WORD $0x4c407441 // ld1 {v1.8h}, [x2]
	WORD $0x6e617402 // uabd v2.8h, v0.8h, v1.8h
	WORD $0x6e626c63 // umin v3.8h, v3.8h, v2.8h
	WORD $0x6e626484 // umax v4.8h, v4.8h, v2.8h
	ADD  R3, R1, R1
	ADD  R4, R2, R2
	SUB  $1, R6, R6
	CBNZ R6, rowLoop16

	WORD $0x6e71a865 // uminv h5, v3.8h
	WORD $0x6e70a886 // umaxv h6, v4.8h
	WORD $0x0e023cac // umov w12, v5.h[0]
	WORD $0x0e023ccd // umov w13, v6.h[0]
	MOVW R12, 0(R5)
	MOVW R13, 4(R5)
	RET
